import base64
import json

ticket_hex = ""
token_hex = ""

ticket_str = bytes.fromhex(ticket_hex).decode('utf-8')
print("Ticket str:", ticket_str)

for part in ticket_str.split('.'):
    padded = part + '=' * ((4 - len(part) % 4) % 4)
    try:
        print("  Decoded part:", base64.urlsafe_b64decode(padded))
    except Exception as e:
        print("  Err:", e)
